<p class="eyebrow">Wallet</p><h1>Withdraw funds</h1><?php if(!$eligible): ?><section class="alert warning"><h2>Withdrawal unavailable</h2><p>Identity verification is required before withdrawals are available.</p><a class="button" href="<?= e(route('dashboard.kyc')) ?>">Start identity verification</a></section><?php else: ?><div class="metric-grid"><article class="metric-card"><span>Spendable balance</span><strong><?= money((int)$wallet['available_balance_minor']) ?></strong></article><article class="metric-card"><span>Reserved</span><strong><?= money((int)$wallet['reserved_balance_minor']) ?></strong></article></div><div class="card-grid"><?php foreach($methods as $item): ?><a class="card" href="<?= e(route('dashboard.withdraw')) ?>?method=<?= e($item['id']) ?>"><h2><?= e($item['name']) ?></h2><p><?= e($item['description']??'Manual withdrawal') ?></p></a><?php endforeach; ?></div><?php if($method): ?><section class="card"><h2><?= e($method['name']) ?></h2><p><?= nl2br(e($method['instructions']??'')) ?></p><form method="post" action="<?= e(route('dashboard.withdraw.submit')) ?>" class="form-stack"><?= app('csrf')->input() ?><input type="hidden" name="method_id" value="<?= e($method['id']) ?>"><label class="field"><span>Amount (<?= e(country()->currencyCode()) ?>)</span><input name="amount" inputmode="decimal" required></label><?php require __DIR__.'/../components/dynamic-form.php'; ?><button class="button">Submit withdrawal request</button></form></section><?php endif; ?><?php endif; ?>
